#!/usr/bin/env bash
# Bundle item 156 lab_summaries_1122 (thread "Site: Add Labour committee", 22 Nov 2569; asked by "Site: Update automatically three times a day")
# Labour 2569, surgical data-only update (no design change). The Senate published four summaries, all Rpublic=1 (checked 22 Nov):
#   main 30/2569 (Thu 12 Nov, 13.00)        เอกสารข่าว ref 11218909
#   main 31/2569 (Thu 19 Nov, 13.00)        จดหมายข่าว ref 11230558
#   welfare sub 25/2569 (Wed 18 Nov, 09.00) จดหมายข่าวฉบับที่ 25 ref 11217525
#   employment sub 24/2569 (Wed 18 Nov, 13.30) เอกสารข่าว ref 11225884
# Easy-read text from those summaries replaces the agenda/"upcoming" text of the four cards:
#  - DATA line + meetings.json / sub-<key>.json: the four records are replaced by the new build's records (chair, chair_role,
#    headline, summary, items, tags, docs with the summary link, no "upcoming"/"agenda_only"/map); the LIVE "media" is kept
#    exactly as it is (pre-meeting videos on video-1, sizes, CAPS untouched). Main 30 and 31: นายชินโชติ แสงสังข์
#    รองประธานคณะกรรมาธิการ คนที่หนึ่ง presided (as the Senate documents say); main 30 gets its room (406–407 ชั้น 4) from the notice.
#  - SHARE_V for the four -> new share cards; EZ.cal entries of these past meetings removed (a fresh build has none);
#    the two "นัดประชุม" plan lines in the subcommittee timelines removed; UPDATED; index.html SUBS: welfare 25 and
#    employment 24 records (docs) + fetched date.
#  - new files: s/30.html, s/31.html, s/welfare-25.html, s/employment-24.html, their cards img/s/<tok>-<hash>.jpg and QR svgs.
#  - i18n-en.json: ADD-ONLY English lines for the new text.
#  m/<n>.html pages and the home upcoming cards follow from DATA in run_bundle (seo.py bundle, hub_snap_sync.py).
#  The listen-button voice of these four is re-recorded by the auto-update thread after this is live (the old recordings stop
#  playing by themselves: their text hash no longer matches).
#  NO contact details, NO private names (no associations, foundations, academics, advisers, complainants). Complaints are
#  written as allegations. Self-contained: the payload is embedded below (base64 tar.gz) and unpacked to a temp folder.
#  Idempotent; no git, no network. Needs $HUB.
set -euo pipefail
: "${HUB:?HUB not set}"
NAME=156_lab_summaries_1122
M="$HUB/labour/2569"
for f in index.html meetings.json sub-welfare.html sub-welfare.json sub-employment.html sub-employment.json i18n-en.json; do
  test -f "$M/$f" || { echo "$NAME: $M/$f missing" >&2; exit 1; }; done
PAY=$(mktemp -d); trap 'rm -rf "$PAY"' EXIT
sed -n '/^__PAYLOAD_BELOW__$/,$p' "$0" | tail -n +2 | base64 -d | tar -xz -C "$PAY"
test -f "$PAY/payload.json" || { echo "$NAME: embedded payload missing" >&2; exit 1; }
(cd "$PAY/files" && find . -type f) | while read -r f; do
  mkdir -p "$(dirname "$M/$f")"; cmp -s "$PAY/files/$f" "$M/$f" || cp -f "$PAY/files/$f" "$M/$f"; done
python3 - "$M" "$PAY/payload.json" "$HUB" <<'PY'
import json, os, re, sys
M, PAYF, HUB = sys.argv[1], sys.argv[2], sys.argv[3]
P = json.load(open(PAYF, encoding='utf-8'))
dec = json.JSONDecoder(); changed = []
UPD = 'const UPDATED="2026-11-23";'
DATES = {'index.html': {30: '2026-11-12', 31: '2026-11-19'}, 'sub-welfare.html': {25: '2026-11-18'}, 'sub-employment.html': {24: '2026-11-18'}}
ser = lambda a: json.dumps(a, ensure_ascii=False, separators=(',', ':')).replace('</', '<\\/')
def put(p, t):
    if open(p, encoding='utf-8').read() != t:
        open(p, 'w', encoding='utf-8').write(t); changed.append(os.path.relpath(p, HUB))
def one(lines, pre):
    idx = [i for i, l in enumerate(lines) if l.startswith(pre)]
    assert len(idx) == 1, f'{pre} not found once'; return idx[0]
def jline(lines, pre, dump):
    i = one(lines, pre); body = lines[i][len(pre):]; val, end = dec.raw_decode(body); tail = body[end:]
    assert pre + dump(val) + tail == lines[i], f'{pre} does not round-trip; not touching it'
    return i, val, tail
def swap(arr, n, date, new, where):
    k = [j for j, m in enumerate(arr) if m.get('n') == n and m.get('date') == date]
    assert len(k) == 1, f'{where}: meeting {n} ({date}) not found once'
    m = json.loads(json.dumps(new))
    if arr[k[0]].get('media'): m['media'] = arr[k[0]]['media']        # live media wins (videos on video-1, sizes)
    else: m.pop('media', None)
    arr[k[0]] = m
for page, d in P['pages'].items():
    dates = DATES[page]
    assert sorted(int(n) for n in d['meetings']) == sorted(dates), f'{page}: payload meetings'
    p = os.path.join(M, page); lines = open(p, encoding='utf-8').read().split('\n')
    i, arr, tail = jline(lines, 'const DATA=', ser)
    for n, date in dates.items(): swap(arr, n, date, d['meetings'][str(n)], page)
    lines[i] = 'const DATA=' + ser(arr) + tail
    i, tl, tail = jline(lines, 'const TL=', lambda a: json.dumps(a, ensure_ascii=False))
    tl2 = [e for e in tl if not (isinstance(e, list) and len(e) >= 7 and e[5] == 'plan' and e[-1] in dates and e[0] == dates[e[-1]])]
    if tl2 != tl: lines[i] = 'const TL=' + json.dumps(tl2, ensure_ascii=False) + tail
    lines[one(lines, 'const UPDATED=')] = UPD
    k2 = one(lines, 'const SHARE_P=')
    mm = re.fullmatch(r'const SHARE_P=("[^"]*"),SHARE_V=(\{[^}]*\}),SHARE_QR=(\[[^\]]*\]);', lines[k2])
    assert mm, f'{page}: SHARE_P line shape changed; not touching it'
    pre, v, q = mm.group(1), json.loads(mm.group(2)), json.loads(mm.group(3))
    assert lines[k2] == f'const SHARE_P={pre},SHARE_V={json.dumps(v)},SHARE_QR={json.dumps(q)};', f'{page}: SHARE_P does not round-trip'
    for n in dates:
        v[str(n)] = d['share'][str(n)]
        if n in d['qr'] and n not in q: q.append(n); q.sort(reverse=True)
    lines[k2] = f'const SHARE_P={pre},SHARE_V={json.dumps(v)},SHARE_QR={json.dumps(q)};'
    i, ez, tail = jline(lines, 'const EZ=', lambda a: json.dumps(a, ensure_ascii=False))
    for n in dates: ez.get('cal', {}).pop(str(n), None)
    lines[i] = 'const EZ=' + json.dumps(ez, ensure_ascii=False) + tail
    if page == 'index.html':
        i, subs, tail = jline(lines, 'const SUBS=', ser)
        for key, b in P['subs'].items():
            x = [s for s in subs if s['key'] == key]; assert len(x) == 1, f'SUBS {key}'
            x = x[0]; x['fetched'] = max(x.get('fetched', ''), b['fetched'])
            for bm in b['meetings']:
                hit = [j for j, y in enumerate(x['meetings']) if y['n'] == bm['n'] and y['date'] == bm['date']]
                if hit: x['meetings'][hit[0]] = bm
                else: x['meetings'].insert(0, bm)
        lines[i] = 'const SUBS=' + ser(subs) + tail
    put(p, '\n'.join(lines))
    jp = os.path.join(M, d['json']); raw = open(jp, encoding='utf-8').read(); ms = json.loads(raw)
    assert json.dumps(ms, ensure_ascii=False, indent=1) == raw, f'{d["json"]} does not round-trip'
    for n, date in dates.items(): swap(ms, n, date, d['jmeetings'][str(n)], d['json'])
    put(jp, json.dumps(ms, ensure_ascii=False, indent=1))
ip = os.path.join(M, 'i18n-en.json'); raw = open(ip, encoding='utf-8').read(); en = json.loads(raw)
assert json.dumps(en, ensure_ascii=False, separators=(',', ':')) == raw, 'i18n-en.json format changed; not touching it'
for kk, vv in P['en'].items():
    en.setdefault(kk, vv)
put(ip, json.dumps(en, ensure_ascii=False, separators=(',', ':')))
changed = sorted(set(changed)); print('156_lab_summaries_1122: changed', len(changed), 'files:', ', '.join(changed) or 'none (already applied)')
PY
python3 - "$M" "$PAY/payload.json" <<'PY'
import json, sys
M, PAYF = sys.argv[1], sys.argv[2]; dec = json.JSONDecoder()
P = json.load(open(PAYF, encoding='utf-8'))
def line(page, pre):
    for l in open(f'{M}/{page}', encoding='utf-8').read().split('\n'):
        if l.startswith(pre): return dec.raw_decode(l[len(pre):])[0]
BAD = ('0 2831', '๐ ๒๘๓๑', 'โทร.', '@senate', 'มนทิรา', 'ทรงพันธ์', 'ตันตระกูล', 'มหาวิทยาลัยเชียงใหม่', 'อิมมานูเอล',
       'ชมรมแหปลา', 'สมาคมเจ้าของเรือไทย', 'สมาคมวิชาชีพชาวเรือไทย', 'ทีดีอาร์ไอ', 'TDRI', 'จารุณี',
       'วิทยาวิโรจน์', 'ธนารักษ์พัฒนาสินทรัพย์', 'ท่าอากาศยานไทย', 'รชฏา', 'ผู้ช่วยเลขานุการ')
CHAIR = {('index.html', 30): 'นายชินโชติ แสงสังข์', ('index.html', 31): 'นายชินโชติ แสงสังข์',
         ('sub-welfare.html', 25): 'พันตำรวจโท สุริยา บาราสัน', ('sub-employment.html', 24): 'นางนงลักษณ์ ก้านเขียว'}
REF = {('index.html', 30): '11218909', ('index.html', 31): '11230558', ('sub-welfare.html', 25): '11217525', ('sub-employment.html', 24): '11225884'}
ROOM = {('index.html', 30): 'ห้องประชุม 406–407 ชั้น 4 อาคารรัฐสภา', ('index.html', 31): 'ห้องประชุม 406–407 ชั้น 4 อาคารรัฐสภา',
        ('sub-welfare.html', 25): 'ห้องประชุมกรรมาธิการ CA 429 ชั้น 4 อาคารรัฐสภา', ('sub-employment.html', 24): 'ห้องประชุมกรรมาธิการ CB 311 ชั้น 3 อาคารรัฐสภา'}
for page, jn in (('index.html', 'meetings.json'), ('sub-welfare.html', 'sub-welfare.json'), ('sub-employment.html', 'sub-employment.json')):
    D = {m['n']: m for m in line(page, 'const DATA=') if m['date'] >= '2026-01-01'}
    J = {m['n']: m for m in json.load(open(f'{M}/{jn}', encoding='utf-8')) if m['date'] >= '2026-01-01'}
    ns = [int(n) for n in P['pages'][page]['meetings']]
    for n in ns:
        for m in (D[n], J[n]):
            assert not m.get('upcoming') and not m.get('agenda_only'), f'{page} {n} still upcoming/agenda-only'
            assert m['chair'] == CHAIR[(page, n)], f'{page} {n} chair'
            assert m['room'] == ROOM[(page, n)], f'{page} {n} room'
            assert any(x['k'] == 'summary' and x['url'].endswith('ref=' + REF[(page, n)]) for x in m['docs']), f'{page} {n} summary link'
            assert [v['kind'] for v in m['media']['videos']] == ['pre'], f'{page} {n} pre video lost'
            assert m['media']['video']['src'].startswith('/video-1/'), f'{page} {n} live video path lost'
            s = json.dumps({k: m.get(k) for k in ('headline', 'summary', 'items', 'tags', 'chair', 'chair_role', 'room')}, ensure_ascii=False)
            for bad in BAD + ('9216', '๙๒๑๖', 'Messenger', 'Line ', 'LINE'): assert bad not in s, f'{bad!r} in {page} {n}'
        tok = f'{page[4:-5]}-{n}' if page != 'index.html' else str(n)
        t = open(f'{M}/s/{tok}.html', encoding='utf-8').read()
        for bad in BAD: assert bad not in t, f'{bad!r} in s/{tok}.html'
        assert 'ระเบียบวาระ' not in D[n]['summary'][:12], f'{page} {n} still agenda text'
    ez = line(page, 'const EZ=')
    for n in ns: assert str(n) not in ez.get('cal', {}), f'{page} {n} calendar entry left'
    t = open(f'{M}/{page}', encoding='utf-8').read()
    assert 'id="vidkind-js"' in t and 'id="novdl-css"' in t and 'id="friction-js"' in t, f'{page}: live layers lost'
caps = line('index.html', 'const CAPS=')
assert '30p' in caps and '31p' in caps, 'CAPS 30p/31p missing'
assert 'welfare-25p' in line('sub-welfare.html', 'const CAPS='), 'CAPS welfare-25p missing'
subs = {x['key']: x for x in line('index.html', 'const SUBS=')}
assert any(d['url'].endswith('ref=11217525') for m in subs['welfare']['meetings'] if m['n'] == 25 for d in m['docs']), 'SUBS welfare 25 summary'
assert any(d['url'].endswith('ref=11225884') for m in subs['employment']['meetings'] if m['n'] == 24 for d in m['docs']), 'SUBS employment 24 summary'
en = json.load(open(f'{M}/i18n-en.json', encoding='utf-8'))
for k in P['en']: assert k in en, 'English line missing: ' + k[:40]
print('156_lab_summaries_1122 OK')
PY
exit 0
